1	/****************************************************************************
2	 * apps/examples/uvc_test/uvc_test.c
3	 *
4	 * USB Camera (UVC) live preview on framebuffer/LCD
5	 * Captures YUYV frames and displays them on /dev/lcd0 in real time.
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
12	#include <errno.h>
13	#include <fcntl.h>
14	#include <unistd.h>
15	#include <syslog.h>
16	#include <sys/ioctl.h>
17	#include <sys/time.h>
18	
19	#include <nuttx/video/video.h>
20	#include <nuttx/video/v4l2_cap.h>
21	#include <nuttx/video/fb.h>
22	#include <nuttx/lcd/lcd_dev.h>
23	#include "tjpgd.h"
