25	/****************************************************************************
26	 * Pre-processor Definitions
27	 ****************************************************************************/
28	
29	#define VIDEO_DEV_PATH    "/dev/video"
30	#define FB_DEV_PATH       "/dev/lcd0"
31	#define TEST_WIDTH        320
32	#define TEST_HEIGHT       240
33	#define TEST_BUF_COUNT    6   /* Deeper queue: more vacant buffers for the UVC
34	                               * stream thread to rotate through, so it never
35	                               * wraps onto the buffer the app is copying out.
36	                               */
37	#define PREVIEW_FRAMES    300   /* ~10s at 30fps; 0 = run forever */
38	#define SAVE_FRAMES       10    /* Save first N frames as .yuv files to /data/ */
39	
40	/****************************************************************************
41	 * Private Types
42	 ****************************************************************************/
43	
44	struct v_buffer
45	{
46	  uint8_t *start;
47	  uint32_t length;
48	};
49	
50	/****************************************************************************
51	 * Private Data
52	 ****************************************************************************/
53	
54	static struct fb_videoinfo_s g_vinfo;
55	static int                   g_fbfd = -1;
56	static int                   g_recfd = -1;  /* /data/capture.yuv */
57	static uint16_t              g_rgbbuf[TEST_WIDTH * TEST_HEIGHT];
58	
59	/****************************************************************************
60	 * tjpgd callbacks for MJPEG decode
61	 ****************************************************************************/
62	
63	struct mjpeg_iodev_s
64	{
65	  const uint8_t *data;
66	  size_t         len;
67	  size_t         pos;
68	};
69	
70	static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
71	{
72	  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
73	  size_t avail = io->len - io->pos;
74	
75	  if (nbyte > avail)
76	    nbyte = avail;
77	
78	  if (buff)
79	    memcpy(buff, io->data + io->pos, nbyte);
80	
81	  io->pos += nbyte;
82	  return nbyte;
83	}
84	
85	static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
86	{
87	  uint8_t *src = (uint8_t *)bitmap;
88	  uint32_t x;
89	  uint32_t y;
90	  uint32_t w = rect->right - rect->left + 1;
91	  uint32_t cpw = jd->width < TEST_WIDTH ? jd->width : TEST_WIDTH;
92	
93	  for (y = rect->top; y <= rect->bottom && y < TEST_HEIGHT; y++)
94	    {
95	      for (x = rect->left; x <= rect->right && x < TEST_WIDTH; x++)
96	        {
97	          uint8_t b = *src++;
98	          uint8_t g = *src++;
99	          uint8_t r = *src++;
100	          g_rgbbuf[y * cpw + x] =
101	            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
102	        }
103	
104	      if (rect->right >= TEST_WIDTH)
105	        src += (rect->right - TEST_WIDTH + 1) * 3;
106	    }
107	
108	  return 1;
109	}
110	
111	/* Private snapshot of one captured frame (YUYV), so the shared V4L2 capture
112	 * buffer can be requeued immediately and not be overwritten mid-processing.
113	 */
114	
115	static uint8_t               g_framecopy[TEST_WIDTH * TEST_HEIGHT * 2];
116	
117	/****************************************************************************
118	 * Private Functions
119	 ****************************************************************************/
120	
121	/* Clamp an int to [0,255] */
122	
123	static inline uint8_t clamp8(int v)
124	{
125	  if (v < 0)
126	    {
127	      return 0;
128	    }
129	
130	  if (v > 255)
131	    {
132	      return 255;
133	    }
134	
135	  return (uint8_t)v;
136	}
