28	// Globals, used for compatibility with Arduino-style sketches.
29	namespace {
30	const tflite::Model* model = nullptr;
31	tflite::MicroInterpreter* interpreter = nullptr;
32	TfLiteTensor* input = nullptr;
33	
34	// In order to use optimized tensorflow lite kernels, a signed int8_t quantized
35	// model is preferred over the legacy unsigned model format. This means that
36	// throughout this project, input images must be converted from unisgned to
37	// signed format. The easiest and quickest way to convert from unsigned to
38	// signed 8-bit integers is to subtract 128 from the unsigned value to get a
39	// signed value.
40	
41	// An area of memory to use for input, output, and intermediate arrays.
42	constexpr int kTensorArenaSize = 136 * 1024;
43	alignas(16) static uint8_t tensor_arena[kTensorArenaSize];
44	}  // namespace
45	
46	// The name of this function is important for Arduino compatibility.
47	void setup() {
48	  tflite::InitializeTarget();
49	
50	  // Map the model into a usable data structure. This doesn't involve any
51	  // copying or parsing, it's a very lightweight operation.
52	  model = tflite::GetModel(g_person_detect_model_data);
53	  if (model->version() != TFLITE_SCHEMA_VERSION) {
54	    MicroPrintf(
55	        "Model provided is schema version %d not equal "
56	        "to supported version %d.",
57	        model->version(), TFLITE_SCHEMA_VERSION);
58	    return;
59	  }
60	
61	  // Pull in only the operation implementations we need.
62	  // This relies on a complete list of all the ops needed by this graph.
63	
64	  // NOLINTNEXTLINE(runtime-global-variables)
65	  static tflite::MicroMutableOpResolver<5> micro_op_resolver;
66	  micro_op_resolver.AddAveragePool2D(tflite::Register_AVERAGE_POOL_2D_INT8());
67	  micro_op_resolver.AddConv2D(tflite::Register_CONV_2D_INT8());
68	  micro_op_resolver.AddDepthwiseConv2D(
69	      tflite::Register_DEPTHWISE_CONV_2D_INT8());
70	  micro_op_resolver.AddReshape();
71	  micro_op_resolver.AddSoftmax(tflite::Register_SOFTMAX_INT8());
72	
73	  // Build an interpreter to run the model with.
74	  // NOLINTNEXTLINE(runtime-global-variables)
75	  static tflite::MicroInterpreter static_interpreter(
76	      model, micro_op_resolver, tensor_arena, kTensorArenaSize);
77	  interpreter = &static_interpreter;
78	
79	  // Allocate memory from the tensor_arena for the model's tensors.
80	  TfLiteStatus allocate_status = interpreter->AllocateTensors();
81	  if (allocate_status != kTfLiteOk) {
82	    MicroPrintf("AllocateTensors() failed");
83	    return;
84	  }
85	
86	  // Get information about the memory area to use for the model's input.
87	  input = interpreter->input(0);
88	}
89	
90	// The name of this function is important for Arduino compatibility.
91	void loop() {
92	  // Get image from provider.
93	  if (kTfLiteOk !=
94	      GetImage(kNumCols, kNumRows, kNumChannels, input->data.int8)) {
95	    MicroPrintf("Image capture failed.");
96	  }
97	
98	  // Run the model on this input and make sure it succeeds.
99	  if (kTfLiteOk != interpreter->Invoke()) {
100	    MicroPrintf("Invoke failed.");
101	  }
102	
103	  TfLiteTensor* output = interpreter->output(0);
104	
105	  // Process the inference results.
106	  int8_t person_score = output->data.uint8[kPersonIndex];
107	  int8_t no_person_score = output->data.uint8[kNotAPersonIndex];
108	  RespondToDetection(person_score, no_person_score);
109	}
