40	{
41	  printf("\nUtility to use tflite micro on nuttx.\n"
42	    "[ -C       ] Compile tflite model into c++ codes.\n"
43	    "[ -E       ] Do once evaluation (for profiling).\n"
44	    "[ -i <str> ] Readable model file path.\n"
45	    "[ -o <str> ] Writable c++ file path.\n"
46	    "[ -p <str> ] Prefix of compiled code.\n"
47	    "[ -a <int> ] Arena size (mempool).\n"
48	    "[ -h       ] Print this message.\n");
49	}
