55	extern "C" int main(int argc, FAR char* argv[])
56	{
57	  const char* modelFileName = nullptr;
58	  const char* codeFileName = nullptr;
59	  const char* prefix = "NXAI";
60	  bool need_compile = false;
61	  bool need_invoke = false;
62	  int arenaSize = 1024 * 8;
63	
64	  int ch;
65	  while ((ch = getopt(argc, argv, "CEhi:o:p:a:")) != EOF)
66	    {
67	      switch (ch)
68	        {
69	          case 'C':
70	            need_compile = true;
71	            break;
72	          case 'E':
73	            need_invoke = true;
74	            break;
75	          case 'p':
76	            prefix = optarg;
77	            break;
78	          case 'i':
79	            modelFileName = optarg;
80	            break;
81	          case 'o':
82	            codeFileName = optarg;
83	            break;
84	          case 'a':
85	            arenaSize = strtol(optarg, NULL, 0);
86	            break;
87	          case 'h':
88	          default:
89	            usage();
90	            return -1;
91	        }
92	    }
93	
94	  if (!modelFileName || !codeFileName)
95	    {
96	      usage();
97	      return -1;
98	    }
99	
100	  std::ifstream ifs(modelFileName, std::ios::binary);
101	  ifs.seekg(0, std::ios::end);
102	  size_t modelSize = ifs.tellg();
103	  std::unique_ptr<uint8_t[]> pModel(new uint8_t[modelSize]);
104	
105	  ifs.seekg(0, std::ios::beg);
106	  ifs.read(reinterpret_cast<char*>(pModel.get()), modelSize);
107	  ifs.close();
108	
109	  /* HACK: can change operators here. */
110	
111	  tflite::MicroMutableOpResolver<8> resolver;
112	  resolver.AddConv2D(tflite::Register_CONV_2D_INT8());
113	  resolver.AddMaxPool2D(tflite::Register_MAX_POOL_2D_INT8());
114	  resolver.AddQuantize(tflite::Register_QUANTIZE_FLOAT32_INT8());
115	  resolver.AddDequantize(tflite::Register_DEQUANTIZE_INT8());
116	  resolver.AddMean(tflite::Register_MEAN_INT8());
117	  resolver.AddReshape();
118	  resolver.AddFullyConnected(tflite::Register_FULLY_CONNECTED_INT8());
119	  resolver.AddSoftmax(tflite::Register_SOFTMAX_INT8());
120	
121	  std::unique_ptr<uint8_t[]> pArena(new uint8_t[arenaSize]);
122	
123	  tflite::MicroProfiler profiler;
124	  tflite::MicroInterpreter interpreter(tflite::GetModel(pModel.get()),
125	    resolver, pArena.get(), arenaSize, nullptr,
126	    reinterpret_cast<tflite::MicroProfilerInterface*>(&profiler));
127	
128	  /* HACK: can add testcases here. */
129	
130	  if (need_invoke)
131	    {
132	      interpreter.Invoke();
133	      profiler.LogCsv();
134	      profiler.LogTicksPerTagCsv();
135	    }
136	
137	  if (need_compile)
138	    {
139	#ifdef TFLITE_MODEL_COMPILER
140	      std::ofstream ofs(codeFileName);
141	      interpreter.Compile(ofs, prefix);
142	      ofs.close();
143	#else
144	      printf("Not supported compiling %s.\n", prefix);
145	#endif
146	    }
147	
148	  printf("nxai done!\n");
149	  return 0;
150	}
